// Select this report's CSV attachment and hand it to the HTTP node as TEXT.
//
// WHY THIS CHANGED (2026-08-12). LP moved from the Report Scheduler to the
// Export Scheduler. Attachments went from
// `mrichard5152_134_260806023534_Jobs by Milestone Date.pdf` to
// `_260812030038_Export.csv` — the report id vanished from the filename, so the
// PDF-era `_134_` test matched nothing and this node returned ZERO items on
// every run. Silently: zero items is not an error, so the POST never fired and
// the failure telemetry never fired either. `revenue_as_of` sat at 2026-08-06
// for six days while this workflow reported "success" in 29ms a day.
//
// Report identity is now decided by LP-MCP's `detectReportFromHeader`; the slug
// in the URL is only a hint. Scope comes from the Gmail subject query.
//
// This loop can only see attachments the TRIGGER downloaded. A trigger without
// `downloadAttachments: true` yields messages with no binary, `bin` is empty,
// and this node returns zero items without erroring — the same silent shape.
//
// The ingest route requires the raw CSV TEXT as the request body. n8n's binary
// body mode sends multipart and overrides Content-Type, which the route rejects
// with 400 "POST the CSV text as the request body". So decode to a string here.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary ?? {};
  for (const key of Object.keys(bin)) {
    const fileName = bin[key]?.fileName ?? '';
    if (!/\.csv$/i.test(fileName)) continue;
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    out.push({
      json: {
        lp_report_id: '134',
        attachment_file_name: fileName,
        csv_text: buf.toString('utf8'),
      },
    });
  }
}
return out;
